/**
 * Research mode (research build only): several study subjects on one clinic device, each in its own IndexedDB
 * database named after a pseudonymous code (e.g. KHU-001), so records can never mix. The device owner's own
 * records stay in the default database. Switching reloads the app so nothing from the previous subject stays in memory.
 */

export const DEFAULT_DB = 'facial-palsy-companion';
const SUBJECTS_KEY = 'fpc.subjects.v1';
const ACTIVE_KEY = 'fpc.activeSubject.v1';

/** Letters, digits and hyphens, 2–20 characters: a study code, never a name. */
export const SUBJECT_CODE = /^[A-Za-z0-9][A-Za-z0-9-]{1,19}$/;

export interface Subject {
  code: string;
  createdAt: string;
}

export const dbNameFor = (code: string | null): string => (code ? `${DEFAULT_DB}::subject::${code}` : DEFAULT_DB);

export function normalizeCode(input: string): string | null {
  const code = input.trim().toUpperCase();
  return SUBJECT_CODE.test(code) ? code : null;
}

const read = <T>(k: string, fallback: T): T => {
  try {
    const v = localStorage.getItem(k);
    return v ? (JSON.parse(v) as T) : fallback;
  } catch {
    return fallback;
  }
};
const write = (k: string, v: unknown): void => {
  try {
    localStorage.setItem(k, JSON.stringify(v));
  } catch {
    /* private mode */
  }
};

export const listSubjects = (): Subject[] => read<Subject[]>(SUBJECTS_KEY, []);

/** The subject whose records are open, or null for the device owner's own records. */
export function activeSubject(): string | null {
  const code = read<string | null>(ACTIVE_KEY, null);
  return code && listSubjects().some((s) => s.code === code) ? code : null;
}

export function addSubject(input: string, now: Date = new Date()): Subject | null {
  const code = normalizeCode(input);
  if (!code || listSubjects().some((s) => s.code === code)) return null;
  const s = { code, createdAt: now.toISOString() };
  write(SUBJECTS_KEY, [...listSubjects(), s]);
  return s;
}

/** Opens a subject's records (null = own records) by reloading the app on that database, at its home screen. */
export function switchSubject(code: string | null): void {
  write(ACTIVE_KEY, code);
  history.replaceState(null, '', '#/');
  location.reload();
}

/** Permanently deletes a subject's records on this device (export first). */
export async function deleteSubject(code: string): Promise<void> {
  await new Promise<void>((resolve, reject) => {
    const req = indexedDB.deleteDatabase(dbNameFor(code));
    req.onsuccess = () => resolve();
    req.onerror = () => reject(req.error);
    req.onblocked = () => resolve();
  });
  write(
    SUBJECTS_KEY,
    listSubjects().filter((s) => s.code !== code),
  );
  if (read<string | null>(ACTIVE_KEY, null) === code) write(ACTIVE_KEY, null);
}
