/**
 * Build-time regulatory profile (VITE_PROFILE). One code base, three
 * distributable configurations with different intended-use scopes:
 *
 *  research        – everything on (investigational use, clinical studies)
 *  samd-assessment – measurement/tracking only: the candidate SaMD scope for a
 *                    first submission; rehab personalisation and research tools off
 *  wellness        – no clinical scales, generic (non-personalised) exercise info
 *
 * Features that change the intended use are switched here, never ad hoc in UI.
 */
export type ProfileId = 'research' | 'samd-assessment' | 'wellness';

export interface Features {
  /** Show estimated House–Brackmann / Sunnybrook values. */
  estimatedScales: boolean;
  /** 'personalized' uses assessment results; 'generic' ignores them; 'off' hides rehab. */
  rehab: 'personalized' | 'generic' | 'off';
  /** Clinician rating entry, agreement statistics, photo-set analysis. */
  researchTools: boolean;
  /** Synthetic demo data. */
  demo: boolean;
}

const PROFILES: Record<ProfileId, Features> = {
  research: { estimatedScales: true, rehab: 'personalized', researchTools: true, demo: true },
  'samd-assessment': { estimatedScales: true, rehab: 'off', researchTools: false, demo: false },
  wellness: { estimatedScales: false, rehab: 'generic', researchTools: false, demo: true },
};

const requested = (import.meta.env.VITE_PROFILE ?? 'research') as ProfileId;
export const PROFILE: ProfileId = requested in PROFILES ? requested : 'research';
export const FEATURES: Readonly<Features> = Object.freeze(PROFILES[PROFILE]);
